/* @autogenerated */
import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { TranslocoService } from '@jsverse/transloco';
import { catchError, combineLatest, from, mergeMap, Observable, take, throwError } from 'rxjs';
import { MfeConfigAdapter } from '@shared/context/config/mfe-config.adapter';
import { environment } from 'app/bootstrap/environment/environment';
import { versionQuery } from '@shared/context/config/i18n-loader.service';
import { DocumentDefinition, DocumentFormat } from './document.model';
import { markdownBlocks } from './markdown-blocks';
import { renderTemplate } from './template-render';

const MIME: Record<DocumentFormat, string> = {
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  pdf: 'application/pdf',
};

/** La plantilla `template` no existe en ningún idioma. */
export class TemplateNotFoundError extends Error {
  constructor(readonly template: string) {
    super('Template not found: ' + template);
  }
}

/**
 * Documentos desde plantillas Markdown de `public/templates/`: carga la plantilla del idioma activo, la rellena con
 * los datos y la convierte a Word o PDF, todo en el navegador. Las librerías se cargan al usarse.
 */
@Injectable({ providedIn: 'root' })
export class DocumentService {
  private readonly http = inject(HttpClient);
  private readonly mfe = inject(MfeConfigAdapter);
  private readonly transloco = inject(TranslocoService);

  /** Markdown de `template` rellenado con lo que aporte `definition.data(item)`. */
  markdown<T>(definition: DocumentDefinition<T>, item: T): Observable<string> {
    return combineLatest([this.template(definition.template), definition.data(item).pipe(take(1))]).pipe(
      take(1),
      mergeMap(([source, data]) => from(renderTemplate(source, data, this.context()))),
    );
  }

  /** Vista previa en HTML del Markdown (para `[innerHTML]`, que Angular sanea). */
  async html(markdown: string): Promise<string> {
    const { marked } = await import('marked');
    return marked.parse(markdown, { async: false, gfm: true }) as string;
  }

  /** El Markdown como fichero del formato pedido. */
  async file(markdown: string, format: DocumentFormat, title = ''): Promise<Blob> {
    const blocks = await markdownBlocks(markdown);
    if (format === 'docx') {
      const { writeDocx } = await import('./docx-writer');
      return writeDocx(blocks, title);
    }
    const { writePdf } = await import('./pdf-writer');
    return writePdf(blocks, title);
  }

  /** Genera y descarga el fichero. */
  async download(markdown: string, format: DocumentFormat, fileName: string): Promise<void> {
    const blob = await this.file(markdown, format, fileName);
    const url = URL.createObjectURL(new Blob([blob], { type: MIME[format] }));
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName + '.' + format;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url));
  }

  /** Texto de la plantilla: la variante más específica del idioma activo que exista (`es-ES`, `es`) o la general. */
  template(path: string): Observable<string> {
    const lang = this.transloco.getActiveLang();
    const candidates = [...new Set([lang, lang.split('-')[0]])].map((variant) => path + '.' + variant).concat(path);
    const base = this.mfe.templatesBase(environment.name);
    const attempt = (index: number): Observable<string> =>
      index >= candidates.length
        ? throwError(() => new TemplateNotFoundError(path))
        : this.http
            .get(base + '/' + candidates[index] + '.md' + versionQuery(), { responseType: 'text' })
            .pipe(catchError(() => attempt(index + 1)));
    return attempt(0);
  }

  private context() {
    return {
      lang: this.transloco.getActiveLang(),
      translate: (key: string, params?: Record<string, unknown>) => this.transloco.translate(key, params),
    };
  }
}
